enum PaymentSessionStatus {
  created('created'),
  processing('processing'),
  verifying('verifying'),
  succeeded('succeeded'),
  failed('failed'),
  cancelled('cancelled'),
  unknown('unknown');

  const PaymentSessionStatus(this.value);

  /// The wire value.
  final String value;

  /// Unknown values never crash a client: they read as [unknown] (api-conventions section 2).
  static PaymentSessionStatus fromJson(Object? v) {
    for (final e in values) {
      if (e.value == v) return e;
    }
    return PaymentSessionStatus.unknown;
  }

  String toJson() => value;
}

